AssistantMessageToolRequest(name='create', tool_call_id='tooluse_MgSeGyT7kyL5pFs4CjoNkY', arguments={'file_text': "/* =============================================================================
   Reset & Base Styles
   ============================================================================= */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --color-primary: #1a1a1a;
  --color-secondary: #6b7280;
  --color-accent: #dc2626;
  --color-light: #f9fafb;
  --color-lighter: #f3f4f6;
  --color-border: #e5e7eb;
  --color-text: #111827;
  --color-text-muted: #6b7280;
  --color-success: #10b981;
  --color-badge: #fbbf24;

  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;

  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;

  --line-height-tight: 1.25;
  --line-height-normal: 1.5;
  --line-height-relaxed: 1.75;

  --border-radius: 0.5rem;
  --border-radius-lg: 1rem;

  --transition-base: 150ms ease-in-out;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  font-size: var(--font-size-base);
  line-height: var(--line-height-normal);
  color: var(--color-text);
  background-color: #ffffff;
  -webkit-font-smoothing: antialiased;
}

/* =============================================================================
   Accessibility
   ============================================================================= */

.skip-to-main {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: white;
  padding: var(--spacing-sm);
  text-decoration: none;
  z-index: 100;
  border-radius: 0 0 var(--border-radius) 0;
}

.skip-to-main:focus {
  top: 0;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* Focus styles for all interactive elements */
button:focus,
a:focus,
input:focus,
textarea:focus,
select:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* =============================================================================
   Typography
   ============================================================================= */

h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: var(--line-height-tight);
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary);
}

h1 {
  font-size: var(--font-size-4xl);
}

h2 {
  font-size: var(--font-size-3xl);
}

h3 {
  font-size: var(--font-size-2xl);
}

h4 {
  font-size: var(--font-size-xl);
}

h5, h6 {
  font-size: var(--font-size-lg);
}

p {
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-accent);
  text-decoration: none;
  transition: color var(--transition-base);
}

a:hover {
  text-decoration: underline;
}

/* =============================================================================
   Layout
   ============================================================================= */

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-lg);
}

.section {
  padding: var(--spacing-2xl) 0;
}

.section--alternate {
  background-color: var(--color-lighter);
}

.section--accent {
  background-color: var(--color-primary);
  color: white;
}

.section--accent h2,
.section--accent h3 {
  color: white;
}

.section--accent p {
  color: #f3f4f6;
}

.section-subtitle {
  font-size: var(--font-size-lg);
  color: var(--color-secondary);
  margin-bottom: var(--spacing-2xl);
  margin-top: calc(-1 * var(--spacing-md));
}

.section-footer {
  display: flex;
  justify-content: center;
  margin-top: var(--spacing-2xl);
}

/* =============================================================================
   Header & Navigation
   ============================================================================= */

.site-header {
  background-color: white;
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 50;
  box-shadow: var(--shadow-sm);
}

.header-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-md) var(--spacing-lg);
}

.logo a {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  color: var(--color-primary);
  text-decoration: none;
}

.logo a:hover {
  text-decoration: none;
  opacity: 0.8;
}

.main-nav {
  flex: 1;
  margin: 0 var(--spacing-xl);
}

.nav-list {
  display: flex;
  list-style: none;
  gap: var(--spacing-lg);
}

.nav-link {
  font-weight: 500;
  color: var(--color-secondary);
  transition: color var(--transition-base);
  position: relative;
}

.nav-link:hover {
  color: var(--color-primary);
  text-decoration: none;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--color-accent);
  transition: width var(--transition-base);
}

.nav-link:hover::after {
  width: 100%;
}

.cart-button {
  position: relative;
  background: none;
  border: none;
  font-size: var(--font-size-lg);
  cursor: pointer;
  padding: var(--spacing-xs);
  transition: transform var(--transition-base);
}

.cart-button:hover {
  transform: scale(1.1);
}

.cart-icon {
  margin-right: var(--spacing-xs);
}

.cart-count {
  position: absolute;
  top: -8px;
  right: -8px;
  background-color: var(--color-accent);
  color: white;
  font-size: var(--font-size-sm);
  font-weight: 600;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* =============================================================================
   Hero Section
   ============================================================================= */

.hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: var(--spacing-2xl);
  padding: var(--spacing-2xl) var(--spacing-lg);
  background: linear-gradient(135deg, #f9fafb 0%, #f3f4f6 100%);
  margin-top: var(--spacing-lg);
}

.hero-content h2 {
  font-size: var(--font-size-4xl);
  margin-bottom: var(--spacing-md);
}

.hero-content p {
  font-size: var(--font-size-lg);
  color: var(--color-secondary);
  margin-bottom: var(--spacing-lg);
}

.hero-image {
  width: 100%;
  height: auto;
  border-radius: var(--border-radius-lg);
  display: block;
}

/* =============================================================================
   Buttons
   ============================================================================= */

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  border-radius: var(--border-radius);
  font-weight: 600;
  transition: all var(--transition-base);
}

.primary-button {
  background-color: var(--color-primary);
  color: white;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: var(--font-size-base);
  display: inline-block;
}

.primary-button:hover {
  background-color: #2d2d2d;
}

.secondary-button {
  background-color: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
  padding: calc(var(--spacing-sm) - 2px) calc(var(--spacing-lg) - 2px);
  font-size: var(--font-size-base);
}

.secondary-button:hover {
  background-color: var(--color-lighter);
}

.cta-button {
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: var(--font-size-base);
  display: inline-block;
}

/* =============================================================================
   Products Grid
   ============================================================================= */

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--spacing-lg);
  margin: var(--spacing-2xl) 0;
}

.product-card {
  background: white;
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: transparent;
}

.product-image-wrapper {
  position: relative;
  overflow: hidden;
  background-color: var(--color-lighter);
  aspect-ratio: 1 / 1;
}

.product-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-base);
}

.product-card:hover .product-image {
  transform: scale(1.05);
}

.badge {
  position: absolute;
  top: var(--spacing-md);
  right: var(--spacing-md);
  background-color: var(--color-success);
  color: white;
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: var(--border-radius);
  font-size: var(--font-size-sm);
  font-weight: 600;
}

.badge.sale {
  background-color: var(--color-accent);
}

.product-info {
  padding: var(--spacing-md);
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.product-link {
  color: var(--color-primary);
  font-weight: 600;
  font-size: var(--font-size-lg);
}

.product-category {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-xs);
}

.product-description {
  color: var(--color-secondary);
  font-size: var(--font-size-sm);
  margin-bottom: var(--spacing-md);
  flex-grow: 1;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
  font-size: var(--font-size-sm);
}

.stars {
  color: #fbbf24;
  letter-spacing: 2px;
}

.rating-count {
  color: var(--color-secondary);
}

.product-price {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-md);
}

.price {
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-primary);
}

.original-price {
  text-decoration: line-through;
  color: var(--color-secondary);
  font-size: var(--font-size-sm);
}

.add-to-cart {
  background-color: var(--color-primary);
  color: white;
  padding: var(--spacing-sm) var(--spacing-lg);
  border-radius: var(--border-radius);
  font-weight: 600;
  width: 100%;
  transition: background-color var(--transition-base);
}

.add-to-cart:hover {
  background-color: #2d2d2d;
}

/* =============================================================================
   Deals Section
   ============================================================================= */

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin: var(--spacing-2xl) 0;
}

.deal-card {
  background: white;
  padding: var(--spacing-2xl);
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--color-border);
  text-align: center;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}

.deal-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.deal-badge {
  display: inline-block;
  background-color: var(--color-accent);
  color: white;
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: var(--border-radius);
  font-size: var(--font-size-sm);
  font-weight: 700;
  margin-bottom: var(--spacing-md);
  align-self: center;
}

.deal-card h3 {
  margin-bottom: var(--spacing-sm);
}

.deal-card p {
  color: var(--color-secondary);
  margin-bottom: var(--spacing-lg);
  flex-grow: 1;
}

.deal-card button {
  align-self: center;
}

/* =============================================================================
   Editorial Section
   ============================================================================= */

.editorial-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--spacing-lg);
  margin: var(--spacing-2xl) 0;
}

.editorial-card {
  background: white;
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
  border: 1px solid var(--color-border);
}

.editorial-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.editorial-image-wrapper {
  overflow: hidden;
  background-color: var(--color-lighter);
  aspect-ratio: 16 / 10;
}

.editorial-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-base);
}

.editorial-card:hover .editorial-image {
  transform: scale(1.05);
}

.editorial-content {
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.article-date {
  font-size: var(--font-size-sm);
  color: var(--color-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-sm);
}

.editorial-link {
  color: var(--color-primary);
  font-weight: 600;
  font-size: var(--font-size-lg);
}

.editorial-card p {
  color: var(--color-secondary);
  margin-bottom: var(--spacing-md);
  flex-grow: 1;
}

.read-more {
  color: var(--color-accent);
  font-weight: 600;
  text-decoration: none;
  transition: all var(--transition-base);
  display: inline-block;
}

.read-more:hover {
  margin-right: -8px;
  margin-left: 8px;
}

/* =============================================================================
   Newsletter Section
   ============================================================================= */

.newsletter-form {
  max-width: 500px;
  margin: var(--spacing-xl) auto 0;
}

.form-group {
  display: flex;
  gap: var(--spacing-sm);
}

#email-input {
  flex: 1;
  padding: var(--spacing-sm) var(--spacing-md);
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: var(--border-radius);
  background-color: rgba(255, 255, 255, 0.1);
  color: white;
  font-size: var(--font-size-base);
}

#email-input::placeholder {
  color: rgba(255, 255, 255, 0.6);
}

#email-input:focus {
  background-color: rgba(255, 255, 255, 0.15);
  border-color: white;
}

.newsletter-form button {
  background-color: white;
  color: var(--color-primary);
  padding: var(--spacing-sm) var(--spacing-lg);
  font-weight: 600;
}

.newsletter-form button:hover {
  background-color: #f3f4f6;
}

.form-help {
  font-size: var(--font-size-sm);
  color: #d1d5db;
  margin-top: var(--spacing-sm);
  text-align: center;
}

/* =============================================================================
   Footer
   ============================================================================= */

.site-footer {
  background-color: var(--color-primary);
  color: #d1d5db;
  padding: var(--spacing-2xl) 0 var(--spacing-lg);
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-xl);
  margin-bottom: var(--spacing-2xl);
}

.footer-section h3 {
  color: white;
  font-size: var(--font-size-lg);
  margin-bottom: var(--spacing-md);
}

.footer-section nav ul {
  list-style: none;
}

.footer-section nav li {
  margin-bottom: var(--spacing-sm);
}

.footer-section a {
  color: #d1d5db;
  text-decoration: none;
  transition: color var(--transition-base);
}

.footer-section a:hover {
  color: white;
  text-decoration: none;
}

.footer-bottom {
  border-top: 1px solid #374151;
  padding-top: var(--spacing-lg);
  text-align: center;
  font-size: var(--font-size-sm);
  color: #9ca3af;
}

/* =============================================================================
   Responsive Design
   ============================================================================= */

@media (max-width: 768px) {
  .container {
    padding: 0 var(--spacing-md);
  }

  .header-content {
    flex-direction: column;
    gap: var(--spacing-md);
    padding: var(--spacing-md);
  }

  .logo {
    order: -1;
  }

  .main-nav {
    margin: 0;
    width: 100%;
  }

  .nav-list {
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--spacing-md);
  }

  .hero {
    grid-template-columns: 1fr;
    padding: var(--spacing-lg);
