/* =============================================================================
   Header & Navigation
   ============================================================================= */

.site-header {
  background-color: white;
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 50;
  box-shadow: var(--shadow-sm);
