.cart-icon {
  margin-right: var(--spacing-xs);
}

.cart-count {
  position: absolute;
  top: -8px;
  right: -8px;
  background-color: var(--color-accent);
  color: white;
  font-size: var(--font-size-sm);
  font-weight: 600;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* =============================================================================
   Hero Section
   ============================================================================= */

.hero {
