+ * ModernShop - Ecommerce Home Page
+ * Interactive functionality for product browsing and shopping
+ */
+
+// ============================================================================
+// State Management
+// ============================================================================
+
+const appState = {
+  cart: [],
+  cartCount: 0,
+  products: [
+    {
+      id: 1,
+      name: 'Minimalist Canvas Tote',
+      price: 79.00,
