+// ============================================================================
+// Cart Management
+// ============================================================================
+
+function initializeCart() {
+  const savedCart = localStorage.getItem('modernshop-cart');
+  if (savedCart) {
+    appState.cart = JSON.parse(savedCart);
+    updateCartCount();
+  }
+}
+
+function addToCart(productId) {
+  const product = appState.products.find(p => p.id === productId);
+  if (!product) return;
+
+  const cartItem = appState.cart.find(item => item.id === productId);
+
+  if (cartItem) {
+    cartItem.quantity += 1;
+  } else {
+    appState.cart.push({
+      ...product,
+      quantity: 1
+    });
+  }
+
+  saveCart();
+  updateCartCount();
+  showCartNotification(product.name);
+}
+
+function saveCart() {
+  localStorage.setItem('modernshop-cart', JSON.stringify(appState.cart));
+}
+
+function updateCartCount() {
+  appState.cartCount = appState.cart.reduce((sum, item) => sum + item.quantity, 0);
+  const cartCountElement = document.querySelector('.cart-count');
+  if (cartCountElement) {
+    cartCountElement.textContent = appState.cartCount;
+    cartCountElement.setAttribute('aria-label', `Shopping cart, ${appState.cartCount} items`);
+  }
+}
+
+// ============================================================================
+// User Feedback
+// ============================================================================
+
+function showCartNotification(productName) {
+  const notification = document.createElement('div');
+  notification.className = 'notification notification--success';
+  notification.setAttribute('role', 'status');
+  notification.setAttribute('aria-live', 'polite');
+  notification.innerHTML = `<strong>${productName}</strong> added to cart`;
+
+  document.body.appendChild(notification);
+
+  // Animate in
+  setTimeout(() => {
+    notification.classList.add('notification--visible');
+  }, 10);
+
+  // Remove after 3 seconds
+  setTimeout(() => {
+    notification.classList.remove('notification--visible');
+    setTimeout(() => {
+      notification.remove();
+    }, 300);
+  }, 3000);
+}
+
+// ============================================================================
+// Event Listeners
+// ============================================================================
+
+function attachEventListeners() {
+  // Add to cart buttons
+  const addToCartButtons = document.querySelectorAll('.add-to-cart');
+  addToCartButtons.forEach(button => {
+    button.addEventListener('click', function() {
+      const productCard = this.closest('.product-card');
+      const productName = productCard.querySelector('.product-link').textContent;
+      
+      // Find the product ID by matching the product name
+      const product = appState.products.find(p => p.name === productName);
+      if (product) {
+        addToCart(product.id);
+      }
+    });
+  });
+
+  // Cart button
+  const cartButton = document.querySelector('.cart-button');
+  if (cartButton) {
+    cartButton.addEventListener('click', function() {
+      if (appState.cartCount === 0) {
+        alert('Your cart is empty');
+      } else {
+        alert(`You have ${appState.cartCount} item(s) in your cart`);
+      }
+    });
+  }
+
+  // Newsletter form
+  const newsletterForm = document.querySelector('.newsletter-form');
+  if (newsletterForm) {
+    newsletterForm.addEventListener('submit', function(e) {
+      e.preventDefault();
+      const emailInput = document.querySelector('#email-input');
+      const email = emailInput.value;
+      
+      if (email) {
+        alert(`Thank you for subscribing with ${email}!`);
+        emailInput.value = '';
+      }
+    });
+  }
+
+  // CTA buttons
+  const ctaButtons = document.querySelectorAll('.cta-button:not(.add-to-cart)');
+  ctaButtons.forEach(button => {
+    button.addEventListener('click', function() {
+      const text = this.textContent;
+      alert(`Navigating to: ${text}`);
+    });
+  });
+
+  // Navigation links smooth scroll
+  const navLinks = document.querySelectorAll('.nav-link');
+  navLinks.forEach(link => {
+    link.addEventListener('click', function(e) {
+      const href = this.getAttribute('href');
+      if (href.startsWith('#')) {
+        e.preventDefault();
+        const target = document.querySelector(href);
+        if (target) {
+          target.scrollIntoView({ behavior: 'smooth' });
+          // Set focus to the section for accessibility
+          if (!target.hasAttribute('tabindex')) {
+            target.setAttribute('tabindex', '-1');
+          }
+          target.focus();
+        }
+      }
+    });
+  });
+}
+
+// ============================================================================
+// Scroll Effects
+// ============================================================================
+
+function handleScroll() {
+  const header = document.querySelector('.site-header');
+  if (window.scrollY > 50) {
+    header.style.boxShadow = 'var(--shadow-md)';
+  } else {
+    header.style.boxShadow = 'var(--shadow-sm)';
+  }
+}
+
+// ============================================================================
+// Lazy Loading
+// ============================================================================
+
+function initializeLazyLoading() {
+  if ('IntersectionObserver' in window) {
+    const imageObserver = new IntersectionObserver((entries, observer) => {
+      entries.forEach(entry => {
+        if (entry.isIntersecting) {
+          // Images are already loaded, but this is a good place for lazy loading in production
+          entry.target.style.opacity = '1';
+          observer.unobserve(entry.target);
+        }
+      });
+    });
+
+    document.querySelectorAll('.product-image, .editorial-image').forEach(img => {
+      imageObserver.observe(img);
+    });
+  }
+}
+
+// ============================================================================
+// Analytics (simple example)
+// ============================================================================
+
+function trackEvent(eventName, eventData = {}) {
+  if (window.gtag) {
+    gtag('event', eventName, eventData);
+  }
+  // In production, send to your analytics service
+  console.log(`Event: ${eventName}`, eventData);
+}
+
+// ============================================================================
+// Keyboard Navigation
+// ============================================================================
+
+function handleKeyboardNavigation() {
+  document.addEventListener('keydown', function(e) {
+    // Close notification with Escape (if implemented)
+    if (e.key === 'Escape') {
+      const notification = document.querySelector('.notification--visible');
+      if (notification) {
+        notification.classList.remove('notification--visible');
+        setTimeout(() => notification.remove(), 300);
+      }
+    }
+  });
+}
+
+// ============================================================================
+// Initialization
+// ============================================================================
+
+document.addEventListener('DOMContentLoaded', function() {
+  // Initialize app
+  initializeCart();
+  attachEventListeners();
+  initializeLazyLoading();
+  handleKeyboardNavigation();
+
+  // Scroll event listener with throttling
+  let lastScrollTime = 0;
+  window.addEventListener('scroll', function() {
+    const now = Date.now();
+    if (now - lastScrollTime > 100) {
+      handleScroll();
+      lastScrollTime = now;
+    }
+  });
+
+  // Track page view
+  trackEvent('page_view', {
+    page_title: 'Home',
+    page_location: window.location.href
+  });
+});
+
+// ============================================================================
+// Notification Styles (injected dynamically)
+// ============================================================================
+
+const notificationStyles = `
+  .notification {
+    position: fixed;
+    bottom: 20px;
